from PIL import Image
import numpy as np

# Load the image
img = Image.open('/home/ctfplayer/ctf_files/short-circuit.jpg')
img_array = np.array(img)

# Get dimensions
height, width = img_array.shape[:2]

def is_dark(pixel):
    return max(pixel) < 30

def find_vertical_lines():
    lines = []
    for x in range(width):
        line_start = None
        for y in range(height):
            if is_dark(img_array[y][x]):
                if line_start is None:
                    line_start = y
            elif line_start is not None:
                if y - line_start > 10:  # Min line length
                    lines.append((x, line_start, y))
                line_start = None
    return lines

def find_horizontal_lines():
    lines = []
    for y in range(height):
        line_start = None
        for x in range(width):
            if is_dark(img_array[y][x]):
                if line_start is None:
                    line_start = x
            elif line_start is not None:
                if x - line_start > 10:  # Min line length
                    lines.append((y, line_start, x))
                line_start = None
    return lines

vertical_lines = find_vertical_lines()
horizontal_lines = find_horizontal_lines()

print(f"Found {len(vertical_lines)} vertical lines")
print(f"Found {len(horizontal_lines)} horizontal lines")

# Analyze line lengths
v_lengths = [end - start for _, start, end in vertical_lines]
h_lengths = [end - start for _, start, end in horizontal_lines]

# Group lines by length
def group_by_length(lengths):
    groups = {}
    for length in lengths:
        group = length // 10 * 10
        groups[group] = groups.get(group, 0) + 1
    return groups

print("\nVertical line lengths (grouped by tens):")
for length, count in sorted(group_by_length(v_lengths).items()):
    print(f"~{length} pixels: {count} lines")

print("\nHorizontal line lengths (grouped by tens):")
for length, count in sorted(group_by_length(h_lengths).items()):
    print(f"~{length} pixels: {count} lines")
